/**
 * Course CRUD actions — modal create/edit, hide/show, delete.
 *
 * @module     local_airpay_courses/course_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_airpay_courses/course_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var openCourseForm = function(courseid, returnFocus) {
        var titleKey = (courseid === 0) ? "addcourse" : "editcourse";
        Str.get_string(titleKey, "local_airpay_courses").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_courses\\form\\edit_course",
                args: {courseid: courseid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmVisibility = function(courseid, coursename, makeVisible, returnFocus) {
        var titleKey = makeVisible ? "showcourse" : "hidecourse";
        var msgKey = makeVisible ? "confirmshow" : "confirmhide";
        var successKey = makeVisible ? "courseshown" : "coursehidden";
        Promise.all([
            Str.get_string(titleKey, "local_airpay_courses"),
            Str.get_string(msgKey, "local_airpay_courses", coursename),
            Str.get_string(successKey, "local_airpay_courses")
        ]).then(function(strings) {
            var title = strings[0], message = strings[1], successMsg = strings[2];
            Notification.confirm(title, message, title, null, function() {
                Ajax.call([{
                    methodname: "local_airpay_courses_toggle_visibility",
                    args: {courseid: courseid, visible: makeVisible}
                }])[0].then(function() {
                    Notification.addNotification({message: successMsg, type: "success"});
                    window.location.reload();
                    return null;
                }).catch(Notification.exception);
            });
            if (returnFocus) {
                setTimeout(function() { returnFocus.focus(); }, 100);
            }
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(courseid, coursename, returnFocus) {
        Promise.all([
            Str.get_string("deletecourse", "local_airpay_courses"),
            Str.get_string("confirmdelete", "local_airpay_courses", coursename),
            Str.get_string("delete", "core"),
            Str.get_string("coursedeleted", "local_airpay_courses")
        ]).then(function(strings) {
            var title = strings[0], message = strings[1],
                deleteLabel = strings[2], successMsg = strings[3];
            Notification.deleteCancelPromise(title, message, deleteLabel, returnFocus)
                .then(function() {
                    Ajax.call([{
                        methodname: "local_airpay_courses_delete_course",
                        args: {courseid: courseid}
                    }])[0].then(function() {
                        Notification.addNotification({message: successMsg, type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                    return true;
                }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var courseid = parseInt(trigger.dataset.courseid || "0", 10);
        var coursename = trigger.dataset.coursename || "this course";
        switch (action) {
            case "create-course":
                event.preventDefault();
                openCourseForm(0, trigger);
                break;
            case "edit-course":
                event.preventDefault();
                openCourseForm(courseid, trigger);
                break;
            case "hide-course":
                event.preventDefault();
                confirmVisibility(courseid, coursename, false, trigger);
                break;
            case "show-course":
                event.preventDefault();
                confirmVisibility(courseid, coursename, true, trigger);
                break;
            case "delete-course":
                event.preventDefault();
                confirmDelete(courseid, coursename, trigger);
                break;
        }
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-courses"]') || document.body;
            if (root.dataset.airpayCoursesInit === "1") return;
            root.dataset.airpayCoursesInit = "1";
            root.addEventListener("click", handleClick);
        }
    };
});
